int main(){int n,m;cin>>n>>m;vector<pair<int,int>>edges(m);for(auto&e:edges)cin>>e.first>>e.second;vector<vector<int>>adj(n+1);vector<int>indeg(n+1,0);for(auto&e:edges){adj[e.first].push_back(e.second);indeg[e.second]++;}queue<int>q;for(int i=1;i<=n;i++)if(!indeg[i])q.push(i);int seen=0;while(!q.empty()){int u=q.front();q.pop();seen++;for(int v:adj[u])if(--indeg[v]==0)q.push(v);}cout<<(seen<n?"YES":"NO")<<"\n";return 0;}

